import { MAX_FILE_NAME_LENGTH } from './files.constants';

/**
 * WHAT: Turns the file name an upload arrived with into one that is safe to
 * store, show and put in a download header.
 *
 * WHY: the name is chosen by the sender. It can contain path parts
 * ("../../etc/passwd"), control characters (which can forge log lines or
 * headers), Windows-reserved characters, or be absurdly long. We therefore
 *   - never use it to decide where a file is stored (see `storage-key.ts` -
 *     the storage path is generated by the server), and
 *   - clean it before keeping it as a DISPLAY name.
 */

/**
 * Some multipart parsers hand us a UTF-8 file name decoded as Latin-1
 * ("Résumé.pdf" arrives as "RÃ©sumÃ©.pdf"). This reverses that when - and only
 * when - the text is exactly what such a mis-decode looks like: every
 * character is within Latin-1 AND re-reading those bytes as UTF-8 succeeds. A
 * name that is already correct (or genuinely Latin-1) is left alone.
 */
export function repairUtf8FileName(name: string): string {
  const looksLatin1 = Array.from(name).every((c) => c.charCodeAt(0) <= 0xff);
  const hasHighBytes = Array.from(name).some((c) => c.charCodeAt(0) >= 0x80);
  if (!looksLatin1 || !hasHighBytes) {
    return name;
  }
  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(
      Buffer.from(name, 'latin1'),
    );
  } catch {
    return name;
  }
}

// Characters that are control codes, or illegal / troublesome in file names on
// common operating systems and in HTTP headers.
// eslint-disable-next-line no-control-regex
const UNSAFE_CHARS = /[\u0000-\u001f\u007f<>:"/\\|?*]/g;

/**
 * Returns a safe display name: no path, no control or reserved characters,
 * collapsed whitespace, no leading/trailing dots or spaces, and at most
 * MAX_FILE_NAME_LENGTH characters with the extension preserved.
 * Falls back to "file" if nothing usable is left.
 */
export function sanitizeFileName(rawName: string): string {
  // 1. Keep only the last path segment, whichever slash style was used.
  const base = rawName.split(/[\\/]/).pop() ?? '';

  // 2. Normalise Unicode, strip unsafe characters, tidy whitespace and dots.
  let name = base
    .normalize('NFC')
    .replace(UNSAFE_CHARS, '_')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^\.+/, '')
    .replace(/[. ]+$/, '');

  if (name === '') {
    return 'file';
  }

  // 3. Cap the length, keeping the extension (it is what tells people - and
  //    operating systems - what the file is).
  if (name.length > MAX_FILE_NAME_LENGTH) {
    const dot = name.lastIndexOf('.');
    const hasShortExtension = dot > 0 && name.length - dot <= 10;
    const extension = hasShortExtension ? name.slice(dot) : '';
    const stem = hasShortExtension ? name.slice(0, dot) : name;
    name = stem.slice(0, MAX_FILE_NAME_LENGTH - extension.length) + extension;
  }
  return name;
}

/**
 * Builds a `Content-Disposition: attachment` header value.
 *
 * `attachment` tells the browser to SAVE the file instead of displaying it -
 * essential, because an uploaded file must never be rendered inside
 * TaskForge's own origin.
 *
 * Two names are sent: a plain-ASCII `filename` for old clients, and an RFC 5987
 * `filename*` carrying the real UTF-8 name percent-encoded. Quotes, and
 * anything non-ASCII, are neutralised in the ASCII one so the name can never
 * break out of the header.
 */
export function contentDispositionAttachment(fileName: string): string {
  const asciiFallback = fileName
    .replace(/[^\x20-\x7e]/g, '_')
    .replace(/["\\%]/g, '_');
  const encoded = encodeURIComponent(fileName).replace(
    /['()*]/g,
    (char) => `%${char.charCodeAt(0).toString(16).toUpperCase()}`,
  );
  return `attachment; filename="${asciiFallback}"; filename*=UTF-8''${encoded}`;
}
